using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using System.Windows;

namespace Copilume;

public static class ClipboardPolicy
{
    public static readonly string[] ExcludedFormats = {
        "ExcludeClipboardContentFromMonitorProcessing", "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType", "com.agilebits.onepassword", "com.agilebits.onepassword.password",
        "de.petermaurer.TransientPasteboardType"
    };
    public static bool ShouldExclude(Func<string, bool> hasFormat, Func<string, byte[]?> read) =>
        ExcludedFormats.Any(hasFormat) || new[] { "CanIncludeInClipboardHistory", "CanUploadToCloudClipboard" }
            .Any(name => hasFormat(name) && (read(name) is not { Length: >= 4 } bytes || BitConverter.ToUInt32(bytes, 0) == 0));
}

internal interface IClipboardAccess
{
    uint Sequence { get; }
    bool Open();
    void Close();
    uint Format(string name);
    bool Has(uint format);
    byte[]? Read(uint format, int maximum);
}

internal sealed class WindowsClipboardAccess(IntPtr window) : IClipboardAccess
{
    public uint Sequence => Native.GetClipboardSequenceNumber();
    public bool Open() => Native.OpenClipboard(window);
    public void Close() => Native.CloseClipboard();
    public uint Format(string name) => Native.RegisterClipboardFormat(name);
    public bool Has(uint format) => Native.IsClipboardFormatAvailable(format);
    public byte[]? Read(uint format, int maximum) => Native.Read(format, maximum);
}

internal sealed class ClipboardService
{
    private readonly IClipboardAccess access;
    private readonly Func<byte[], bool, Task<StoredImage>> decode;
    private readonly History history;
    private readonly Action changed;
    private readonly Action<string> status;
    private uint seen;
    private int epoch;
    private bool busy;
    internal bool IsBusy => busy;
    internal ClipboardService(IntPtr window, History history, Action changed, Action<string> status,
        IClipboardAccess? access = null, Func<byte[], bool, Task<StoredImage>>? decode = null)
    {
        this.access = access ?? new WindowsClipboardAccess(window);
        this.decode = decode ?? ((bytes, dib) => Task.Run(() => ImageCodec.Normalize(bytes, dib)));
        this.history = history; this.changed = changed; this.status = status; seen = this.access.Sequence;
    }
    internal void Invalidate() { epoch++; seen = access.Sequence; }
    internal void Capture()
    {
        if (busy || history.Paused || seen == access.Sequence) return;
        busy = true;
        _ = CaptureSerial();
    }
    private async Task CaptureSerial()
    {
        try { await CaptureCore(); }
        finally
        {
            busy = false;
            if (!history.Paused && seen != access.Sequence) Capture();
        }
    }
    private async Task CaptureCore()
    {
        uint sequence = access.Sequence;
        if (sequence == seen || history.Paused) return;
        int ticket = ++epoch;
        for (int attempt = 0; attempt < 5; attempt++)
        {
            if (ticket != epoch || sequence != access.Sequence || history.Paused) return;
            if (!access.Open()) { await Task.Delay(40); continue; }
            byte[]? image = null; bool dib = false; string? text = null;
            try
            {
                bool Has(string name) => access.Has(access.Format(name));
                byte[]? Read(string name) => access.Read(access.Format(name), 4);
                seen = sequence;
                if (ClipboardPolicy.ShouldExclude(Has, Read) || access.Has(15)) return; // CF_HDROP: no files.
                uint png = access.Format("PNG");
                if (access.Has(png)) image = access.Read(png, 32_000_000);
                else if (access.Has(17) || access.Has(8))
                { dib = true; image = access.Read(access.Has(17) ? 17u : 8u, 32_000_000); }
                else if (access.Read(13, 4_000_002) is { } unicode)
                {
                    text = Encoding.Unicode.GetString(unicode);
                    int terminator = text.IndexOf('\0'); if (terminator >= 0) text = text[..terminator];
                }
            }
            finally { access.Close(); }
            try
            {
                Clip? clip = image != null ? new Clip { Image = await decode(image, dib) }
                    : text != null ? new Clip { Text = text } : null;
                if (ticket == epoch && sequence == access.Sequence && !history.Paused && clip != null && history.Capture(clip)) changed();
            }
            catch (Exception error) when (error is IOException or InvalidDataException or FileFormatException or NotSupportedException or ArgumentException or System.Runtime.InteropServices.COMException or InvalidOperationException)
            { if (ticket == epoch) status("Imagem não capturada: formato inválido ou acima dos limites."); }
            return;
        }
        seen = sequence;
        status("Área de transferência ocupada. A próxima cópia será capturada.");
    }
    internal bool Write(Clip clip, bool singleLine)
    {
        try
        {
            var data = new DataObject();
            // Our writes must not be recaptured, synced to the cloud, or added to Windows history.
            data.SetData("CanIncludeInClipboardHistory", new MemoryStream(new byte[4]));
            data.SetData("CanUploadToCloudClipboard", new MemoryStream(new byte[4]));
            data.SetData("ExcludeClipboardContentFromMonitorProcessing", new MemoryStream(new byte[] { 1 }));
            if (clip.Image is { } image)
            {
                data.SetData("PNG", new MemoryStream(image.Png));
                data.SetImage(ImageCodec.Decode(image.Png));
            }
            else data.SetText(singleLine ? clip.SingleLine : clip.Text, TextDataFormat.UnicodeText);
            System.Windows.Clipboard.SetDataObject(data, true);
            Invalidate();
            return true;
        }
        catch (Exception error) when (error is System.Runtime.InteropServices.ExternalException or IOException or InvalidDataException or FileFormatException or ArgumentException or InvalidOperationException or NotSupportedException)
        { status("Não foi possível copiar. A área de transferência pode estar ocupada."); return false; }
    }
}
